        {"새찬송가":"220", "통일찬송가":"169", "제목":"예수님은 누구신가", "선정이유":"모든 지혜의 근원이신 그리스도를 높임"},
        {"새찬송가":"197", "통일찬송가":"161", "제목":"달고 오묘한 그 말씀", "선정이유":"하나님의 말씀의 풍요로움을 노래함"},
        {"새찬송가":"280", "통일찬송가":"239", "제목":"내 주는 강한 성이요", "선정이유":"그리스도 안에서의 풍요와 승리를 선포함"}
