        {"구절":"고전 12:8", "연결점":"어떤 이에게는 지혜의 말씀을 어떤 이에게는 지식의 말씀을 - 말씀과 지식의 은사", "구분":"신약"},
        {"구절":"대하 1:12", "연결점":"하나님이 솔로몬에게 지혜와 지식을 주심 - 하나님이 주신 지식의 예표", "구분":"구약"},
        {"구절":"사 11:2", "연결점":"지혜와 총명의 영 지식과 여호와를 경외하는 영 - 메시아에게 주어진 지식", "구분":"구약"},
        {"구절":"벧전 4:10", "연결점":"각각 은사를 받은대로 하나님의 각양 은혜를 맡은 선한 청지기같이 - 은사의 청지기적 사용", "구분":"신약"},
        {"구절":"약 1:5", "연결점":"너희 중에 누구든지 지혜가 부족하거든 모든 사람에게 후히 주시는 하나님께 구하라", "구분":"신약"}
