        {"상황":"교회 지도자들의 차이로 인해 파벌이 생겨난 상황", "성경원리":"고린도 교회의 파벌주의는 지도자에 대한 과도한 집착에서 비롯되었다. 지도자보다 그리스도가 중심이어야 한다", "실제적용":"좋아하는 목사나 지도자가 달라도 같은 그리스도를 믿는다면 하나다. 지도자에 대한 의견 차이가 형제 관계를 끊을 이유가 되어서는 안 된다"},
        {"상황":"화해하기 싫고 용서가 되지 않는 분", "성경원리":"'온전히 합하라'는 명령은 감정이 따라올 때까지 기다리는 것이 아닌 의지적 결단을 요구한다", "실제적용":"감정이 따르지 않아도 먼저 화해의 행동을 취하라. 행동이 감정을 바꾼다. 상대방을 위해 기도하는 것부터 시작하라"}
