        {"구절":"시 33:10", "연결점":"여호와께서 열방의 도모를 폐하시며 민족들의 사상을 무효화하신다", "구분":"구약"},
        {"구절":"잠 3:5-7", "연결점":"자신의 명철을 의지하지 말고 여호와를 신뢰하라는 지혜 원리", "구분":"구약"},
        {"구절":"롬 11:33-34", "연결점":"하나님의 지혜와 지식의 깊이는 측량할 수 없으며, 누가 주의 마음을 알았느냐", "구분":"신약"},
        {"구절":"고전 3:19-20", "연결점":"이 세상 지혜는 하나님께서 어리석게 보시는 것이라", "구분":"신약"},
        {"구절":"골 2:3", "연결점":"그리스도 안에 지혜와 지식의 모든 보화가 감추어져 있다", "구분":"신약"},
        {"구절":"약 3:17", "연결점":"위로부터 난 지혜는 순결하고 화평하고 관용하다", "구분":"신약"}
